CREATE TYPE public.app_role AS ENUM ('student','teacher','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', avatar_url text, welcomed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'student', UNIQUE(user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.is_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'teacher') OR public.has_role(auth.uid(),'admin') $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_staff());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.classes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, course text NOT NULL, institution text NOT NULL, leader text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.classes TO anon,authenticated; GRANT ALL ON public.classes TO service_role;
ALTER TABLE public.classes ENABLE ROW LEVEL SECURITY;
CREATE POLICY classes_read ON public.classes FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.class_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES public.classes(id), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(class_id,user_id));
GRANT SELECT ON public.class_members TO authenticated; GRANT ALL ON public.class_members TO service_role;
ALTER TABLE public.class_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY members_read ON public.class_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_staff());
CREATE FUNCTION public.is_member(_class uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.class_members WHERE class_id=_class AND user_id=auth.uid()) $$;
CREATE TABLE public.teachers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.teachers TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.teachers TO authenticated; GRANT ALL ON public.teachers TO service_role;
ALTER TABLE public.teachers ENABLE ROW LEVEL SECURITY;
CREATE POLICY teachers_read ON public.teachers FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY teachers_manage ON public.teachers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES public.classes(id), name text NOT NULL UNIQUE, teacher_id uuid REFERENCES public.teachers(id) ON DELETE SET NULL, category text NOT NULL DEFAULT 'general' CHECK(category IN('general','technical','language','humanities')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subjects TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.subjects TO authenticated; GRANT ALL ON public.subjects TO service_role;
ALTER TABLE public.subjects ENABLE ROW LEVEL SECURITY;
CREATE POLICY subjects_read ON public.subjects FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY subjects_manage ON public.subjects FOR ALL TO authenticated USING(public.is_staff()) WITH CHECK(public.is_staff());
CREATE TABLE public.class_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES public.classes(id), subject_id uuid REFERENCES public.subjects(id), weekday integer NOT NULL CHECK(weekday BETWEEN 1 AND 5), start_time time NOT NULL, end_time time NOT NULL, is_break boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_time>start_time), CHECK((is_break AND subject_id IS NULL) OR (NOT is_break AND subject_id IS NOT NULL)), UNIQUE(class_id,weekday,start_time));
GRANT SELECT ON public.class_schedules TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.class_schedules TO authenticated; GRANT ALL ON public.class_schedules TO service_role;
ALTER TABLE public.class_schedules ENABLE ROW LEVEL SECURITY;
CREATE POLICY schedule_read ON public.class_schedules FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY schedule_manage ON public.class_schedules FOR ALL TO authenticated USING(public.is_staff() AND public.is_member(class_id)) WITH CHECK(public.is_staff() AND public.is_member(class_id));
CREATE TABLE public.assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES public.classes(id), subject_id uuid REFERENCES public.subjects(id), title text NOT NULL, description text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '', due_at timestamptz NOT NULL, priority text NOT NULL DEFAULT 'normal' CHECK(priority IN('normal','high','urgent')), assessment_type text NOT NULL DEFAULT 'Trabalho', author_id uuid NOT NULL REFERENCES public.profiles(id), attachment_path text, allow_replacement boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.assignments TO authenticated; GRANT ALL ON public.assignments TO service_role;
ALTER TABLE public.assignments ENABLE ROW LEVEL SECURITY;
CREATE POLICY assignments_read ON public.assignments FOR SELECT TO authenticated USING(public.is_member(class_id));
CREATE POLICY assignments_manage ON public.assignments FOR ALL TO authenticated USING(public.is_staff() AND public.is_member(class_id)) WITH CHECK(public.is_staff() AND public.is_member(class_id) AND author_id=auth.uid());
CREATE TABLE public.assignment_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL REFERENCES public.assignments(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES public.profiles(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','in_progress','completed')), comment text NOT NULL DEFAULT '', file_path text, history jsonb NOT NULL DEFAULT '[]', observation text NOT NULL DEFAULT '', evaluated boolean NOT NULL DEFAULT false, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(assignment_id,student_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.assignment_submissions TO authenticated; GRANT ALL ON public.assignment_submissions TO service_role;
ALTER TABLE public.assignment_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY submissions_read ON public.assignment_submissions FOR SELECT TO authenticated USING(student_id=auth.uid() OR (public.is_staff() AND EXISTS(SELECT 1 FROM public.assignments a WHERE a.id=assignment_id AND public.is_member(a.class_id))));
CREATE POLICY submissions_insert ON public.assignment_submissions FOR INSERT TO authenticated WITH CHECK(student_id=auth.uid() AND NOT evaluated AND observation='' AND EXISTS(SELECT 1 FROM public.assignments a WHERE a.id=assignment_id AND public.is_member(a.class_id)));
CREATE POLICY submissions_update ON public.assignment_submissions FOR UPDATE TO authenticated USING(student_id=auth.uid() OR public.is_staff()) WITH CHECK(student_id=auth.uid() OR public.is_staff());
CREATE FUNCTION public.guard_submission() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a public.assignments; BEGIN SELECT * INTO a FROM public.assignments WHERE id=NEW.assignment_id; IF TG_OP='UPDATE' AND (NEW.assignment_id<>OLD.assignment_id OR NEW.student_id<>OLD.student_id) THEN RAISE EXCEPTION 'Entrega não pode mudar de aluno ou atividade'; END IF; IF NOT public.is_staff() THEN IF TG_OP='UPDATE' AND (NEW.evaluated IS DISTINCT FROM OLD.evaluated OR NEW.observation IS DISTINCT FROM OLD.observation OR OLD.evaluated) THEN RAISE EXCEPTION 'Somente professores podem avaliar'; END IF; IF TG_OP='UPDATE' AND OLD.submitted_at IS NOT NULL AND NOT a.allow_replacement THEN RAISE EXCEPTION 'Substituição não permitida'; END IF; IF NEW.status='completed' AND a.due_at<now() THEN RAISE EXCEPTION 'Prazo de entrega encerrado'; END IF; END IF; IF NEW.status='completed' THEN NEW.submitted_at=now(); ELSE NEW.submitted_at=NULL; END IF; IF TG_OP='UPDATE' AND NEW.file_path IS DISTINCT FROM OLD.file_path AND OLD.file_path IS NOT NULL THEN NEW.history=OLD.history || jsonb_build_array(jsonb_build_object('path',OLD.file_path,'submitted_at',OLD.submitted_at)); ELSE IF TG_OP='UPDATE' THEN NEW.history=OLD.history; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER submission_guard BEFORE INSERT OR UPDATE ON public.assignment_submissions FOR EACH ROW EXECUTE FUNCTION public.guard_submission();
CREATE TABLE public.calendar_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES public.classes(id), title text NOT NULL, description text NOT NULL DEFAULT '', starts_at timestamptz NOT NULL, category text NOT NULL DEFAULT 'Evento', author_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.calendar_events TO authenticated; GRANT ALL ON public.calendar_events TO service_role;
ALTER TABLE public.calendar_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES public.classes(id), title text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Geral', priority text NOT NULL DEFAULT 'normal', pinned boolean NOT NULL DEFAULT false, author_id uuid NOT NULL REFERENCES public.profiles(id), attachment_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.announcements TO authenticated; GRANT ALL ON public.announcements TO service_role;
ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.study_materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES public.classes(id), subject_id uuid REFERENCES public.subjects(id), title text NOT NULL, description text NOT NULL DEFAULT '', external_url text, file_path text, author_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.study_materials TO authenticated; GRANT ALL ON public.study_materials TO service_role;
ALTER TABLE public.study_materials ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['calendar_events','announcements','study_materials'] LOOP EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING(public.is_member(class_id))', t||'_read',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING(public.is_staff() AND public.is_member(class_id)) WITH CHECK(public.is_staff() AND public.is_member(class_id) AND author_id=auth.uid())',t||'_manage',t); END LOOP; END $$;
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', path text NOT NULL DEFAULT '/', is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
GRANT UPDATE(is_read) ON public.notifications TO authenticated;
REVOKE UPDATE ON public.notifications FROM authenticated; GRANT UPDATE(is_read) ON public.notifications TO authenticated;
CREATE TABLE public.student_suggestions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES public.classes(id), author_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.student_suggestions TO authenticated; GRANT ALL ON public.student_suggestions TO service_role;
ALTER TABLE public.student_suggestions ENABLE ROW LEVEL SECURITY;
CREATE POLICY suggestions_read ON public.student_suggestions FOR SELECT TO authenticated USING(author_id=auth.uid() OR public.is_staff());
CREATE POLICY suggestions_create ON public.student_suggestions FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND public.is_member(class_id) AND status='pending');
CREATE POLICY suggestions_moderate ON public.student_suggestions FOR UPDATE TO authenticated USING(public.is_staff()) WITH CHECK(public.is_staff());
CREATE POLICY suggestions_delete ON public.student_suggestions FOR DELETE TO authenticated USING(public.is_staff());
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, resource text NOT NULL, record_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_admin ON public.audit_logs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,resource,record_id) VALUES(auth.uid(),TG_OP,TG_TABLE_NAME,COALESCE(NEW.id,OLD.id)); RETURN COALESCE(NEW,OLD); END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['assignments','class_schedules','announcements','calendar_events','study_materials','user_roles','teachers','subjects','student_suggestions'] LOOP EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_change()',t||'_audit',t); END LOOP; END $$;
CREATE FUNCTION public.set_user_role(target_user uuid,new_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso exclusivo de administradores'; END IF; IF target_user=auth.uid() THEN RAISE EXCEPTION 'Você não pode alterar seu próprio papel'; END IF; UPDATE public.user_roles SET role=new_role WHERE user_id=target_user; END $$;
REVOKE ALL ON FUNCTION public.set_user_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_user_role(uuid,public.app_role) TO authenticated;
CREATE FUNCTION public.on_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'student'); INSERT INTO public.class_members(class_id,user_id) SELECT id,NEW.id FROM public.classes; RETURN NEW; END $$;
CREATE TRIGGER renova_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.on_signup();
CREATE FUNCTION public.notify_class() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; BEGIN p=CASE TG_TABLE_NAME WHEN 'assignments' THEN '/atividades' WHEN 'announcements' THEN '/avisos' ELSE '/calendario' END; INSERT INTO public.notifications(user_id,title,description,path) SELECT user_id,CASE WHEN TG_OP='UPDATE' THEN 'Prazo atualizado: ' ELSE 'Novo: ' END || NEW.title, NEW.description,p FROM public.class_members WHERE class_id=NEW.class_id AND user_id<>NEW.author_id; RETURN NEW; END $$;
CREATE TRIGGER new_assignment AFTER INSERT ON public.assignments FOR EACH ROW EXECUTE FUNCTION public.notify_class();
CREATE TRIGGER changed_deadline AFTER UPDATE OF due_at ON public.assignments FOR EACH ROW WHEN(NEW.due_at IS DISTINCT FROM OLD.due_at) EXECUTE FUNCTION public.notify_class();
CREATE TRIGGER new_notice AFTER INSERT ON public.announcements FOR EACH ROW EXECUTE FUNCTION public.notify_class();
CREATE TRIGGER new_event AFTER INSERT ON public.calendar_events FOR EACH ROW EXECUTE FUNCTION public.notify_class();
CREATE FUNCTION public.notify_suggestion() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.notifications(user_id,title,description,path) VALUES(NEW.author_id,'Sugestão '||CASE NEW.status WHEN 'approved' THEN 'aprovada' ELSE 'recusada' END,NEW.title,'/avisos'); END IF; RETURN NEW; END $$;
CREATE TRIGGER suggestion_result AFTER UPDATE ON public.student_suggestions FOR EACH ROW EXECUTE FUNCTION public.notify_suggestion();
CREATE POLICY private_submissions_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='submissions' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.is_staff()));
CREATE POLICY private_submissions_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='submissions' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.assignments a WHERE a.id::text=(storage.foldername(name))[2] AND public.is_member(a.class_id) AND a.due_at>=now()));
CREATE POLICY private_materials_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='materials' AND EXISTS(SELECT 1 FROM public.class_members WHERE user_id=auth.uid()));
CREATE POLICY private_materials_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='materials' AND public.is_staff() AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY private_materials_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='materials' AND public.is_staff());
CREATE INDEX members_user_idx ON public.class_members(user_id);
CREATE INDEX schedule_day_idx ON public.class_schedules(class_id,weekday,start_time);
CREATE INDEX assignments_due_idx ON public.assignments(class_id,due_at);
CREATE INDEX submissions_student_idx ON public.assignment_submissions(student_id);
CREATE INDEX notification_user_idx ON public.notifications(user_id,is_read);
CREATE INDEX events_date_idx ON public.calendar_events(class_id,starts_at);
ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications;